// LAB: Enforce scheduler state transitions
// Use an enum to model Ready, Running, and Waiting. Permit dispatch, blocking, and wakeup only from their valid starting states.
// This starter verifies the original example. Extend it to satisfy the lab checks.
#include <cassert>
#include <iostream>
#include <string>

int main() {
    std::string a = "running";
    std::string b = "ready";
    a = "waiting";
    b = "running";
    std::cout << "A=" << a << " B=" << b << '\n';
    a = "ready";
    std::cout << "A=" << a << " B=" << b << '\n';
}

#include <cassert>
#include <iostream>

enum class State { Ready, Running, Waiting };
bool transition(State& state, State from, State to) {
    if(state != from) return false;
    state = to;
    return true;
}

int main() {
    State process = State::Ready;
    assert(transition(process,State::Ready,State::Running));
    assert(transition(process,State::Running,State::Waiting));
    assert(!transition(process,State::Ready,State::Running) && process == State::Waiting);
    assert(transition(process,State::Waiting,State::Ready));
    std::cout << "ready -> running -> waiting -> ready\n";
}

